#include <iostream>
#include <string>
#include <set>

using namespace std;

int main() {
    string s;
    cin >> s;

    set<string> oks;

    for (int i = 0; i < static_cast<int>(s.size()); ++i) {
        for (int j = i; j < static_cast<int>(s.size()); ++j) {
            int ss = i;
            int e = j;
            bool ok = true;

            while (e > ss) {
                if (s[ss] != s[e]) {
                    ok = false;
                    break;
                }
                ++ss;
                --e;
            }

            if (ok) {
                oks.insert(s.substr(i, j - i + 1));
            }
        }
    }

    cout << oks.size();

    return 0;
}

